from pathlib import Path
import ast

expected = {'feature.patch', 'security.patch'}
assert {path.name for path in Path('candidate').iterdir()} == expected
allowed = {'app/service.py', 'app/operations.py'}
for filename in sorted(expected):
    patch = (Path('candidate') / filename).read_text(encoding='utf-8')
    headers = [line for line in patch.splitlines() if line.startswith(('--- ', '+++ '))]
    assert headers
    for header in headers:
        prefix = '--- a/' if header.startswith('--- ') else '+++ b/'
        assert header.startswith(prefix), header
        assert header[len(prefix):] in allowed, header
    print(filename + ': UTF-8 unified diff; only existing permitted paths.')
for path in Path('inputs/B').rglob('*'):
    if path.is_file():
        assert path.read_bytes() == (Path('.scratch/B') / path.relative_to('inputs/B')).read_bytes()
for version in ('U', 'R'):
    for filename in allowed:
        tree = ast.parse((Path('.scratch') / version / filename).read_text(encoding='utf-8'))
        for node in ast.walk(tree):
            if isinstance(node, ast.ImportFrom):
                assert node.module.split('.')[0] in {'app', 'html'}
            elif isinstance(node, ast.Import):
                assert all(alias.name.split('.')[0] in {'app', 'html'} for alias in node.names)
print('Candidate contains exactly two patches; baseline copy matches fixed B; implementation parses.')
